namespace App\Filament\Pages;

use App\Filament\Concerns\HasMonthlyPeriodFilter;
use Filament\Pages\Page;
use Illuminate\Contracts\Support\Htmlable;

/**
 * Andamento mensile dei km per tipo di attività, con filtro periodo su
 * base mensile (mese da / mese a) invece del DatePicker giornaliero della
 * Dashboard: la granularità dei dati qui è già mensile.
 */
class Trend extends Page
{
    use HasMonthlyPeriodFilter;

    protected static string $view = 'filament.pages.trend';

    public static function getNavigationIcon(): string|Htmlable|null
    {
        return 'heroicon-o-presentation-chart-line';
    }

    public function getTitle(): string|Htmlable
    {
        return 'Trend';
    }

    public static function getNavigationLabel(): string
    {
        return 'Trend';
    }
}

